{
  "packet_id": "H6-T02-2",
  "claim_id": "C015",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C015",
    "value": "Unmatched exports should remain in the investigation with their limitations retained.",
    "scope": "Retention does not make unmatched cases comparable.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P006 explicitly calls for retaining unmatched cases with their limitations while making matched comparisons where available."
    }
  },
  "signal_basis": {
    "component_id": "C015_signal_basis",
    "value": "The comparison distinguishes matched and unmatched exports, records consistency, inconsistency or unknown evidence with reliability and diagnostic value, and checks whether removing uncertain evidence changes the ranking.",
    "scope": "Unmatched cases remain qualified evidence; their retention supplies no assurance of comparability or diagnostic strength.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply qualified retention, explicit assessment of evidence quality, and sensitivity to uncertain evidence."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C015_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The bounded procedural claim is supported without an additional unresolved empirical relation."
    }
  },
  "rationale": "Retaining cases with explicit limitations is licensed by a comparison that can mark evidence unknown, assess its diagnostic value, and test sensitivity to its inclusion. The claim requires preserving evidence for investigation, without granting unmatched cases the inferential weight of comparable cases.",
  "uncertainty": "The usefulness of any particular unmatched export remains uncertain, but the claim does not assert that each retained case will discriminate among explanations.",
  "anomalies": []
}
